inline const CatalogRangedAsset* catalogRangedAsset(uint32_t item,const std::array<uint32_t,4>& guid){
 for(const auto& a:catalogRangedAssets){if(a.item==item)return a.guid==guid?&a:nullptr;if(a.item>item)break;}return nullptr;
}
inline bool catalogBowAsset(uint32_t item,const std::array<uint32_t,4>& guid){const auto a=catalogRangedAsset(item,guid);return a&&catalogRangedRigs[a->rig].type==4;}
